package dao

import (
	"github.com/liaisonio/liaison/pkg/liaison/repo/model"
	"github.com/stretchr/testify/require"
	"gorm.io/driver/sqlite"
	"gorm.io/gorm"
	"path/filepath"
	"testing"
)

// Exact pre-feature schema, generated by GORM just like an existing install.
type legacyOpeningProxy struct {
	gorm.Model
	ApplicationID  uint                 `gorm:"column:application_id;type:int;not null"`
	Name           string               `gorm:"column:name;type:varchar(255);not null"`
	Port           int                  `gorm:"column:port;type:int;not null"`
	Status         model.ProxyStatus    `gorm:"column:status;type:int;not null"`
	Description    string               `gorm:"column:description;type:varchar(255);not null"`
	AccessProtocol model.AccessProtocol `gorm:"column:access_protocol;type:varchar(32);not null;default:'';index"`
	HTTPEntryMode  string               `gorm:"column:http_entry_mode;type:varchar(16);not null;default:''"`
}

func (legacyOpeningProxy) TableName() string { return "proxies" }

func TestProxyOpeningMigrationPreservesLegacyAccess(t *testing.T) {
	db, err := gorm.Open(sqlite.Open(filepath.Join(t.TempDir(), "upgrade.db")), &gorm.Config{})
	require.NoError(t, err)
	sqlDB, err := db.DB()
	require.NoError(t, err)
	defer sqlDB.Close()
	require.NoError(t, db.AutoMigrate(&legacyOpeningProxy{}))
	require.NoError(t, db.Create(&legacyOpeningProxy{Model: gorm.Model{ID: 1}, ApplicationID: 1, Name: "Legacy TCP", Port: 15432, Status: model.ProxyStatusRunning, AccessProtocol: model.AccessProtocolTCP}).Error)
	require.NoError(t, db.AutoMigrate(&model.Proxy{}))
	require.NoError(t, db.AutoMigrate(&model.Proxy{}))
	d := &dao{db: db}
	p, err := d.GetProxyByID(1)
	require.NoError(t, err)
	require.Equal(t, "continuous", p.TCPOpeningMode)
	require.Equal(t, 10, p.TCPOpeningDurationSeconds)
	require.Equal(t, 15432, p.Port)
	p.TCPOpeningMode, p.TCPOpeningDurationSeconds = "on_demand", 30
	require.NoError(t, d.UpdateProxy(p))
	p, err = d.GetProxyByID(1)
	require.NoError(t, err)
	require.Equal(t, "on_demand", p.TCPOpeningMode)
	require.Equal(t, 30, p.TCPOpeningDurationSeconds)
}
